/*
 * A041590  Numerators of continued fraction convergents to sqrt(313).
 * https://oeis.org/A041590
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   a(0)=17 a(n)=a(n-1)*a_n + a(n-2) for n>=1, where a_n are the
 *            continued‑fraction coefficients of sqrt(313). The coefficients
 *            are generated by the standard algorithm for the continued
 *            fraction of a square root
 * Range:     u8 n <= 3, u16 n <= 8, u32 n <= 16, u64 n <= 37, u128 n <= 76,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    const uint64_t D  = 313ULL;   /* the square‑free integer */
    const uint64_t a0 = 17ULL;    /* floor(sqrt(313)) */

    /* p_{-1}=1, p_0=a0  */
    seq_t p_nm2 = 1;
    seq_t p_nm1 = (seq_t)a0;

    if (n == 0) {
        return (seq_t)a0;
    }

    /* initial values for the continued‑fraction algorithm */
    uint64_t m = 0;
    uint64_t d = 1;
    uint64_t a = a0;

    /* iterate the recurrence for n steps */
    for (idx_t i = 1; i <= n; ++i) {
        m = d * a - m;                /* m_{k+1} = d_k*a_k - m_k */
        d = (D - m * m) / d;          /* d_{k+1} = (D - m_{k+1}^2) / d_k */
        a = (a0 + m) / d;             /* a_{k+1} = floor((a0 + m_{k+1}) / d_{k+1}) */
        seq_t p = (seq_t)a * p_nm1 + p_nm2; /* p_k = a_k p_{k-1} + p_{k-2} */
        p_nm2 = p_nm1;
        p_nm1 = p;
    }
    return p_nm1;
}
